const formatBTC = (n: number) => `${n.toFixed(2)} BTC`;
const short = (s: string, n = 17) => s.length > n ? `${s.slice(0, n - 1)}…` : s;

function Panel({ title, meta, children, className = "", action }: { title?: string; meta?: string; children: ReactNode; className?: string; action?: ReactNode }) {
  return <section className={`panel ${className}`}>
    {(title || meta || action) && <div className="panel-header"><div><div className="panel-title">{title}</div>{meta && <div className="panel-meta mt-14" style={{ marginTop: 4 }}>{meta}</div>}</div>{action}</div>}
    <div className="panel-body">{children}</div>
  </section>;
}
function MetricCard({ label, value, delta, tone = "green", icon }: { label: string; value: string | number; delta: string; tone?: string; icon?: ReactNode }) {
  return <div className="metric-card"><div className="flex-between"><div className="metric-label">{label}</div><span style={{ color: tone === "orange" ? "#f4a64d" : "#4bcff5" }}>{icon}</span></div><div className="metric-value">{value}</div><div className={`metric-delta ${tone === "orange" ? "warn" : tone === "cyan" ? "cyan" : ""}`}>{delta}</div></div>;
}
function AnomalyPill({ status }: { status: Tx["anomaly"] }) { return <span className={`tag ${status === "ANOMALOUS" ? "red" : "green"}`}>{status}</span>; }
function Priority({ value }: { value: Wallet["priority"] }) { return <span className={`badge-priority ${value.toLowerCase()}`}>{value}</span>; }
function ChartTip({ active, payload, label }: any) { if (!active || !payload?.length) return null; return <div className="tooltip-card"><p className="mono">{label}</p>{payload.map((p: any) => <p key={p.dataKey}><span style={{ color: p.color }}>●</span> {p.name}: <b>{p.value}</b></p>)}</div>; }

